package com.mediconnect.prescription.domain; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="prescription_items") public class PrescriptionItemEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="prescription_id",nullable=false) private PrescriptionEntity prescription; @Column(nullable=false,length=180) private String drugName; @Column(nullable=false,length=120) private String dose; @Column(nullable=false,length=120) private String frequency; @Column(nullable=false,length=120) private String duration; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private MedicationValidationStatus validationStatus; protected PrescriptionItemEntity(){} public PrescriptionItemEntity(String drugName,String dose,String frequency,String duration,MedicationValidationStatus validationStatus){this.drugName=drugName;this.dose=dose;this.frequency=frequency;this.duration=duration;this.validationStatus=validationStatus;} void assignTo(PrescriptionEntity prescription){this.prescription=prescription;} public UUID getId(){return id;} public String getDrugName(){return drugName;} public String getDose(){return dose;} public String getFrequency(){return frequency;} public String getDuration(){return duration;} public MedicationValidationStatus getValidationStatus(){return validationStatus;} }
